import{_ as a,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2020-01-22 :: Ceph Science User Group Meeting","description":"","frontmatter":{"title":"2020-01-22 :: Ceph Science User Group Meeting","date":"2020-01-22T00:00:00.000Z","updated":"2020-01-24T00:00:00.000Z","tags":["Ceph","科学计算","分布式存储","社区活动","用户组会议"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-01-22_-_-_Ceph_Science_User_Group_Meeting.md","filePath":"posts/2020/2020-01-22_-_-_Ceph_Science_User_Group_Meeting.md","lastUpdated":1780460162000}'),o={name:"posts/2020/2020-01-22_-_-_Ceph_Science_User_Group_Meeting.md"};function r(n,e,h,p,s,_){return l(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次Ceph科学用户组虚拟会议由Kevin主持，聚焦于Ceph在科学计算和大型集群中的应用。与会者包括Liam Monahan、Tom Bennett等，共同分享了使用经验、遇到的问题以及未来的计划。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Ceph集群使用经验分享</strong></p><ul><li>Liam Monahan介绍了其维护的3.5PB Ceph集群，主要应用于科学计算和机器学习。</li><li>Tom Bennett分享了使用Ceph存储Meerkat望远镜数据的经验，目前存储了数亿个对象。</li></ul></li><li><p><strong>Ceph版本升级和问题讨论</strong></p><ul><li>讨论了从Luminous到Nautilus的升级过程，以及在升级至14.2.5和14.2.6版本时遇到的心跳问题和OMAP对象问题。</li><li>讨论了Ceph集群在扩展时遇到的OSD映射创建延迟问题，并分享了通过调整参数来解决的经验。</li></ul></li><li><p><strong>Ceph集群管理和优化</strong></p><ul><li>讨论了在多代硬件上运行Ceph集群的挑战，特别是从文件存储迁移到BlueStore时的问题。</li><li>分享了关于Ceph集群中PG的自动缩放和客户端扩展的经验。</li></ul></li><li><p><strong>未来计划和社区活动</strong></p><ul><li>讨论了即将到来的Ceph社区活动，如Ceph Day和Cephalocon，以及如何组织“Birds of a Feather”会议。</li><li>确定了下一次会议将在三月份举行，但可能会根据Cephalocon的时间进行调整。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>下一次会议计划在三月份举行，具体日期将根据社区成员的可用性进行调整。</li><li>将通过邮件列表和私人邮件通知所有参与者下一次会议的详细信息。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续监控和调整Ceph集群的性能，特别是在升级到新版本后。</li><li>探索和实施Ceph集群的优化策略，如PG自动缩放和客户端扩展。</li><li>组织和参与Ceph社区活动，如Ceph Day和Cephalocon，以促进知识共享和技术交流。</li></ul><h4 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h4><ul><li>会议中提到的Ceph相关工具和参数调整将在后续的邮件和文档中进一步详细说明。</li><li>鼓励社区成员在会议后继续通过邮件列表和私人邮件进行交流和讨论。</li></ul><p>本次会议为Ceph用户提供了宝贵的交流平台，促进了经验的分享和技术问题的解决，同时也加强了社区成员之间的联系。</p>',12)])])}const d=a(o,[["render",r]]);export{c as __pageData,d as default};
